def transform(grid):
    g = np.asarray(grid)
    H, W = g.shape
    bg = background(g)
    out = np.full((2 * H, 2 * W), bg, dtype=int)
    emit(out, f"Allocate a blank {2*H}x{2*W} canvas (twice the input size) filled with background {bg}.")
    for y in range(H):
        for x in range(W):
            out[2 * y:2 * y + 2, 2 * x:2 * x + 2] = g[y, x]
        if np.any(g[y] != bg):
            emit(out, f"Scale input row {y}: each cell becomes a 2x2 block in output rows {2*y}-{2*y+1}.")
    emit(out, "Final canvas: every input cell has been enlarged to a 2x2 block of its colour.")
    return out
